insert into questions (id, type, data, status) values ('q_mtf_opioid_active_metabolites_001', 'MTF', '{"dateAdded":"2026-09-09","rotationIndex":98,"stem":"These opioids have clinically significant active metabolites:","choices":["Methadone","Pethidine","Alfentanil","Oxycodone","Morphine"],"correct":[false,true,false,true,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Whether an opioid has a clinically significant active metabolite matters most in renal impairment, where renally-cleared metabolites accumulate and cause toxicity. Morphine, pethidine and oxycodone are the classic offenders; fentanyl, alfentanil and methadone are not.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Methadone is metabolised hepatically (mainly CYP3A4, also CYP2B6/CYP2D6) to inactive metabolites (principally EDDP). The absence of an active, renally-cleared metabolite is one reason methadone is relatively favourable in renal impairment, although accumulation of the parent drug and QT prolongation still require caution.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Pethidine undergoes N-demethylation to norpethidine, an active, neuroexcitatory metabolite that lowers the seizure threshold and causes tremor, myoclonus and agitation. Norpethidine accumulates with repeated dosing and in renal impairment, and is the main reason pethidine is avoided for prolonged or repeated use.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Alfentanil is metabolised hepatically via CYP3A4 to inactive metabolites (noralfentanil), with no clinically significant active metabolite accumulation. With fentanyl, it is one of the preferred opioids in renal impairment.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Oxycodone is metabolised via CYP3A4 to noroxycodone (weakly active) and via CYP2D6 to oxymorphone (active, and more potent than the parent). Both the parent drug and its metabolites are renally excreted and accumulate in renal impairment.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Morphine undergoes hepatic glucuronidation to morphine-6-glucuronide (an active analgesic and respiratory depressant) and morphine-3-glucuronide (not analgesic but neuroexcitatory). Both are renally excreted and accumulate substantially in renal impairment, making morphine one of the least suitable opioids in this setting.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioid Active Metabolites</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">An active metabolite is one that retains pharmacological activity &mdash; analgesic, respiratory-depressant or neuroexcitatory. The clinical significance depends on the metabolite&rsquo;s potency and its route of clearance: renally-cleared active metabolites accumulate when renal function is poor.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids with clinically significant active metabolites</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Active metabolite(s)</th><th>Clinical consequence</th></tr><tr><td>Morphine</td><td>Morphine-6-glucuronide (active analgesic, respiratory depressant); morphine-3-glucuronide (neuroexcitatory, non-analgesic)</td><td>Accumulate in renal impairment &mdash; sedation, respiratory depression, myoclonus</td></tr><tr><td>Pethidine</td><td>Norpethidine (neuroexcitatory)</td><td>Seizures, tremor, myoclonus, agitation; worse with repeated dosing or renal impairment</td></tr><tr><td>Oxycodone</td><td>Oxymorphone (active, more potent; via CYP2D6); noroxycodone (weakly active; via CYP3A4)</td><td>Parent and metabolites renally excreted &mdash; accumulate in renal impairment</td></tr><tr><td>Codeine</td><td>Morphine (via CYP2D6)</td><td>Marked interindividual variability &mdash; ultra-rapid metabolisers risk toxicity, poor metabolisers get little analgesia</td></tr><tr><td>Tramadol</td><td>O-desmethyltramadol (M1; active at the &mu;-receptor, via CYP2D6)</td><td>Contributes much of the opioid analgesia; accumulates in renal impairment</td></tr><tr><td>Diamorphine (heroin)</td><td>6-monoacetylmorphine, then morphine (&rarr; M6G / M3G)</td><td>Rapidly hydrolysed &mdash; effectively a morphine prodrug</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids without clinically significant active metabolites</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Metabolism and note</th></tr><tr><td>Fentanyl</td><td>Hepatic CYP3A4 &rarr; norfentanyl (inactive). Preferred in renal impairment</td></tr><tr><td>Alfentanil</td><td>Hepatic CYP3A4 &rarr; inactive metabolites. Preferred in renal impairment</td></tr><tr><td>Remifentanil</td><td>Non-specific plasma / tissue esterases &rarr; inactive acid metabolite; independent of hepatic and renal function</td></tr><tr><td>Methadone</td><td>Hepatic (CYP3A4, CYP2B6, CYP2D6) &rarr; inactive EDDP. Favourable in renal impairment; watch QT and parent-drug accumulation</td></tr><tr><td>Hydromorphone</td><td>Hepatic glucuronidation &rarr; hydromorphone-3-glucuronide: not analgesic but neuroexcitatory &mdash; a partial exception that still warrants caution in renal impairment</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical relevance</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Morphine, pethidine and oxycodone have renally-cleared active or toxic metabolites &mdash; dose-reduce, extend the dosing interval, or avoid in renal impairment</td></tr><tr><td>Fentanyl and alfentanil are generally preferred when renal function is poor</td></tr><tr><td>Pethidine&rsquo;s norpethidine makes it unsuitable for repeated dosing or use in renal impairment, whatever the indication</td></tr><tr><td>Hydromorphone-3-glucuronide is a partial exception &mdash; analgesically inactive but neuroexcitatory, so caution still applies in renal impairment</td></tr></table></div></div></div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_fibromyalgia_psychological_therapy_evidence_001', 'SBA', '{"dateAdded":"2026-09-09","rotationIndex":99,"question":"Which of the following psychological therapies has the least evidence for effectiveness in the management of fibromyalgia?","choices":["Psychodynamic therapy","Acceptance and Commitment Therapy (ACT)","Cognitive Behavioural Therapy (CBT)","Dialectical Behaviour Therapy (DBT)","Behavioural activation"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Psychological therapy is a core part of multidisciplinary fibromyalgia management. The evidence base is strongest for CBT and increasingly supportive for ACT; psychodynamic therapy is neither recommended nor well studied for this condition.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Psychodynamic therapy has the weakest evidence base of the options listed for fibromyalgia. It is not recommended in fibromyalgia guidance (e.g. EULAR) and has not been shown in controlled trials to improve fibromyalgia outcomes.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> ACT has a growing and reasonably supportive evidence base in fibromyalgia and chronic pain, targeting psychological flexibility, acceptance of pain and values-based action rather than direct symptom reduction; it is a recommended option in EULAR guidance.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> CBT has the strongest and most established evidence base of the psychological therapies for fibromyalgia and is recommended in multiple guidelines as part of a multidisciplinary approach.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> DBT has a more limited fibromyalgia-specific evidence base than CBT or ACT, but some components (e.g. distress tolerance, emotion regulation) have theoretical and emerging relevance to chronic pain &mdash; giving it more traction than psychodynamic therapy.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Behavioural activation is a component of broader CBT-based programmes rather than a stand-alone therapy; it is used in chronic pain and fibromyalgia to address pain-related avoidance and deconditioning, and so carries more supporting evidence than psychodynamic therapy.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Psychological Therapies in Chronic Pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Several psychological therapies are used in chronic pain and fibromyalgia. They differ in their mechanism and in the strength of their evidence base: CBT is the best established, ACT is increasingly well supported, and psychodynamic therapy is neither recommended nor well studied for chronic pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cognitive Behavioural Therapy (CBT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A structured, time-limited therapy based on the premise that thoughts, emotions and behaviours are interconnected, and that maladaptive patterns can perpetuate and amplify experiences including chronic pain. It has the strongest and most established evidence base of the psychological therapies for fibromyalgia and is recommended across guidelines as part of a multidisciplinary approach.</p><table style=\"margin:0\"><tr><th>Components</th></tr><tr><td>Cognitive restructuring &mdash; identifying and challenging unhelpful, distorted pain-related thoughts (e.g. catastrophising, &ldquo;my pain means I am doing damage&rdquo;)</td></tr><tr><td>Behavioural activation &mdash; graded activity and exposure, pacing</td></tr><tr><td>Psychoeducation &mdash; understanding the pain experience and the mind&ndash;body relationship</td></tr><tr><td>Relaxation and coping-skills training &mdash; e.g. progressive muscle relaxation, diaphragmatic breathing</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Acceptance and Commitment Therapy (ACT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A &ldquo;third-wave&rdquo; behavioural therapy that aims to increase <strong>psychological flexibility</strong> &mdash; the ability to accept unwanted internal experiences (pain, thoughts, emotions) without struggling against them, while committing to actions aligned with personal values &mdash; rather than focusing on reducing or eliminating the pain itself. It has a growing and reasonably supportive evidence base in fibromyalgia and chronic pain, and is a recommended option in EULAR guidance.</p><div style=\"text-align:center\"><img src=\"images/act-hexaflex.svg\" alt=\"The ACT hexaflex: six core processes of psychological flexibility arranged around a hexagon — acceptance, cognitive defusion, present-moment awareness, values, committed action and self-as-context\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The six core processes (the &ldquo;hexaflex&rdquo;): acceptance, cognitive defusion, present-moment awareness / mindfulness, values clarification, committed action, and self-as-context.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Behavioural activation</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Structured engagement in meaningful and rewarding activities, based on the principle that avoidance and withdrawal maintain and worsen distress and disability. It is a component of broader CBT-based programmes rather than a stand-alone therapy, and in chronic pain it targets pain-related avoidance and deconditioning.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Dialectical Behaviour Therapy (DBT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Originally developed for borderline personality disorder and chronic emotional dysregulation. DBT combines standard cognitive-behavioural techniques with mindfulness and acceptance, structured around balancing the &ldquo;dialectic&rdquo; of acceptance and change. Its fibromyalgia-specific evidence base is more limited than that of CBT or ACT.</p><table style=\"margin:0\"><tr><th>Components</th></tr><tr><td>Mindfulness &mdash; the core skill underpinning the other modules; present-moment, non-judgemental awareness</td></tr><tr><td>Distress tolerance &mdash; surviving crises and intense distress without making things worse</td></tr><tr><td>Emotion regulation &mdash; identifying, understanding and modulating intense emotional responses</td></tr><tr><td>Interpersonal effectiveness &mdash; navigating relationships and communicating needs assertively while maintaining self-respect</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Psychodynamic therapy</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Rooted in psychoanalytic theory, exploring how unconscious processes, unresolved past conflicts and early developmental / relational experiences influence present-day thoughts, emotions and behaviour, including symptom experience and coping style. It has the weakest evidence base of the therapies listed here for fibromyalgia and is not a recommended intervention for chronic pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Biofeedback</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The patient is connected to monitoring equipment that provides real-time visual or auditory feedback on physiological processes normally outside conscious awareness &mdash; e.g. muscle tension (EMG), skin temperature, heart rate variability. Through repeated practice and operant conditioning the patient learns to consciously influence these processes to reduce pain, muscle tension or physiological arousal. It relies on physiological self-regulation and feedback learning, <strong>not</strong> on mindfulness or present-moment acceptance.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Compassion-Focused Therapy (CFT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Aimed at people who experience high levels of shame and self-criticism, helping them develop self-compassion and activate a calming, &ldquo;soothing&rdquo; emotional system rather than remaining dominated by threat-based (fight/flight) responses to their pain and symptoms. Mindfulness practice is used as a core technique to access the calm, self-soothing state.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mindfulness across the therapies</div><table style=\"margin:0\"><tr><th>Therapy</th><th>Mindfulness a core component?</th></tr><tr><td>CBT</td><td>Not core to traditional CBT; many modern chronic-pain CBT programmes add mindfulness-based elements as adjuncts</td></tr><tr><td>ACT</td><td>Yes &mdash; present-moment awareness is one of the six core processes</td></tr><tr><td>DBT</td><td>Yes &mdash; the foundational core skill underpinning the other modules</td></tr><tr><td>CFT</td><td>Yes &mdash; used to reach a calm, self-soothing state before compassion work</td></tr><tr><td>Biofeedback</td><td>No &mdash; works through physiological feedback and operant conditioning</td></tr></table></div></div></div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_psychological_therapy_mindfulness_001', 'SBA', '{"dateAdded":"2026-09-09","rotationIndex":100,"question":"Which of the following does NOT incorporate mindfulness?","choices":["Cognitive Behavioural Therapy (CBT)","Acceptance and Commitment Therapy (ACT)","Biofeedback","Dialectical Behaviour Therapy (DBT)","Compassion-Focused Therapy"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Mindfulness &mdash; cultivating present-moment, non-judgemental awareness &mdash; is a core or foundational component of several psychological therapies used in chronic pain, but it is not part of biofeedback, which works through a distinct, physiologically-driven mechanism.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Traditional CBT is not built around mindfulness, but many modern chronic-pain CBT programmes incorporate mindfulness-based elements (relaxation, present-moment attention techniques) as adjunctive components.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Present-moment awareness / mindfulness is one of the defined core processes of ACT&rsquo;s psychological flexibility model.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> Biofeedback gives patients real-time physiological data (e.g. muscle tension via EMG, skin temperature, heart rate variability) and, through operant conditioning, teaches them to consciously control these parameters to reduce pain or tension. It relies on physiological self-regulation and feedback learning, not on mindfulness or present-moment acceptance practices.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Mindfulness is the foundational core skill of DBT, underpinning the other modules (distress tolerance, emotion regulation, interpersonal effectiveness).</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> CFT incorporates mindfulness practices as a core technique, helping patients access a calm, self-soothing state before compassion-building exercises directed at themselves and others.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Psychological Therapies in Chronic Pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Several psychological therapies are used in chronic pain and fibromyalgia. They differ in their mechanism and in the strength of their evidence base: CBT is the best established, ACT is increasingly well supported, and psychodynamic therapy is neither recommended nor well studied for chronic pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cognitive Behavioural Therapy (CBT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A structured, time-limited therapy based on the premise that thoughts, emotions and behaviours are interconnected, and that maladaptive patterns can perpetuate and amplify experiences including chronic pain. It has the strongest and most established evidence base of the psychological therapies for fibromyalgia and is recommended across guidelines as part of a multidisciplinary approach.</p><table style=\"margin:0\"><tr><th>Components</th></tr><tr><td>Cognitive restructuring &mdash; identifying and challenging unhelpful, distorted pain-related thoughts (e.g. catastrophising, &ldquo;my pain means I am doing damage&rdquo;)</td></tr><tr><td>Behavioural activation &mdash; graded activity and exposure, pacing</td></tr><tr><td>Psychoeducation &mdash; understanding the pain experience and the mind&ndash;body relationship</td></tr><tr><td>Relaxation and coping-skills training &mdash; e.g. progressive muscle relaxation, diaphragmatic breathing</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Acceptance and Commitment Therapy (ACT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A &ldquo;third-wave&rdquo; behavioural therapy that aims to increase <strong>psychological flexibility</strong> &mdash; the ability to accept unwanted internal experiences (pain, thoughts, emotions) without struggling against them, while committing to actions aligned with personal values &mdash; rather than focusing on reducing or eliminating the pain itself. It has a growing and reasonably supportive evidence base in fibromyalgia and chronic pain, and is a recommended option in EULAR guidance.</p><div style=\"text-align:center\"><img src=\"images/act-hexaflex.svg\" alt=\"The ACT hexaflex: six core processes of psychological flexibility arranged around a hexagon — acceptance, cognitive defusion, present-moment awareness, values, committed action and self-as-context\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The six core processes (the &ldquo;hexaflex&rdquo;): acceptance, cognitive defusion, present-moment awareness / mindfulness, values clarification, committed action, and self-as-context.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Behavioural activation</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Structured engagement in meaningful and rewarding activities, based on the principle that avoidance and withdrawal maintain and worsen distress and disability. It is a component of broader CBT-based programmes rather than a stand-alone therapy, and in chronic pain it targets pain-related avoidance and deconditioning.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Dialectical Behaviour Therapy (DBT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Originally developed for borderline personality disorder and chronic emotional dysregulation. DBT combines standard cognitive-behavioural techniques with mindfulness and acceptance, structured around balancing the &ldquo;dialectic&rdquo; of acceptance and change. Its fibromyalgia-specific evidence base is more limited than that of CBT or ACT.</p><table style=\"margin:0\"><tr><th>Components</th></tr><tr><td>Mindfulness &mdash; the core skill underpinning the other modules; present-moment, non-judgemental awareness</td></tr><tr><td>Distress tolerance &mdash; surviving crises and intense distress without making things worse</td></tr><tr><td>Emotion regulation &mdash; identifying, understanding and modulating intense emotional responses</td></tr><tr><td>Interpersonal effectiveness &mdash; navigating relationships and communicating needs assertively while maintaining self-respect</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Psychodynamic therapy</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Rooted in psychoanalytic theory, exploring how unconscious processes, unresolved past conflicts and early developmental / relational experiences influence present-day thoughts, emotions and behaviour, including symptom experience and coping style. It has the weakest evidence base of the therapies listed here for fibromyalgia and is not a recommended intervention for chronic pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Biofeedback</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The patient is connected to monitoring equipment that provides real-time visual or auditory feedback on physiological processes normally outside conscious awareness &mdash; e.g. muscle tension (EMG), skin temperature, heart rate variability. Through repeated practice and operant conditioning the patient learns to consciously influence these processes to reduce pain, muscle tension or physiological arousal. It relies on physiological self-regulation and feedback learning, <strong>not</strong> on mindfulness or present-moment acceptance.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Compassion-Focused Therapy (CFT)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Aimed at people who experience high levels of shame and self-criticism, helping them develop self-compassion and activate a calming, &ldquo;soothing&rdquo; emotional system rather than remaining dominated by threat-based (fight/flight) responses to their pain and symptoms. Mindfulness practice is used as a core technique to access the calm, self-soothing state.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mindfulness across the therapies</div><table style=\"margin:0\"><tr><th>Therapy</th><th>Mindfulness a core component?</th></tr><tr><td>CBT</td><td>Not core to traditional CBT; many modern chronic-pain CBT programmes add mindfulness-based elements as adjuncts</td></tr><tr><td>ACT</td><td>Yes &mdash; present-moment awareness is one of the six core processes</td></tr><tr><td>DBT</td><td>Yes &mdash; the foundational core skill underpinning the other modules</td></tr><tr><td>CFT</td><td>Yes &mdash; used to reach a calm, self-soothing state before compassion work</td></tr><tr><td>Biofeedback</td><td>No &mdash; works through physiological feedback and operant conditioning</td></tr></table></div></div></div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_scs_superficial_infection_001', 'SBA', '{"dateAdded":"2026-09-09","rotationIndex":101,"question":"A patient develops redness, swelling and localised tenderness at the implantable pulse generator (IPG) site 10 days after spinal cord stimulator implantation. Blood tests show a raised CRP, ESR and white cell count. There is no wound discharge, dehiscence or exposed hardware, and no neurological deficit or systemic sepsis. What is the most appropriate initial management?","choices":["Oral antibiotics (e.g. flucloxacillin)","Admit, observe and start IV antibiotics in consultation with microbiology","Remove the IPG only","Remove the entire system (IPG and leads)","Discharge with outpatient wound review in one week"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">This is a <strong>superficial surgical site infection</strong> &mdash; erythema, swelling and tenderness confined to the incision / pocket, with no wound breakdown, exposed hardware, neurological compromise or systemic sepsis. Raised inflammatory markers are expected and do not by themselves indicate deep or device-related infection. Per NACC (Neurostimulation Appropriateness Consensus Committee) guidance, superficial SCS infections can be treated with oral antibiotics alone, without hospital admission or device removal.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Oral antibiotics directed at the likely pathogens &mdash; staphylococci and streptococci (e.g. flucloxacillin, or a first-generation cephalosporin) &mdash; are first-line for a superficial SSI after SCS implantation, typically for 7&ndash;10 days, with close outpatient review to confirm resolution.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Admission, IV antibiotics and microbiology input are appropriate for <em>deep</em> infection (involving the implant or hardware, wound dehiscence, systemic sepsis or neurological compromise) and are excessive as initial management of an uncomplicated superficial infection.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Removing the IPG alone is not indicated for superficial infection; device explantation is reserved for deep, implant-associated infection that fails antibiotic therapy or shows more severe features.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Removing the entire system is likewise reserved for deep infection involving the implant, and is premature for a superficial, localised presentation.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Simple outpatient review defers necessary treatment &mdash; antibiotics should be started promptly, even though hospital admission is not required.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Spinal Cord Stimulation &mdash; Infection Management</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">SCS-related infection is classified by depth (CDC surgical site infection definitions, adopted by NACC). Superficial incisional infection is treated medically; deep or implant-associated infection almost always requires device removal to achieve cure.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification</div><table style=\"margin:0\"><tr><th>Type</th><th>Involves</th><th>Timing</th></tr><tr><td>Superficial incisional SSI</td><td>Skin and subcutaneous tissue only</td><td>Within 30 days of the operation</td></tr><tr><td>Deep incisional SSI</td><td>Deeper soft tissue (muscle, fascia) and/or the implant itself</td><td>Within 30 days, or longer where an implant is involved</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Superficial infection &mdash; management</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Oral antibiotics targeting staphylococci / streptococci (e.g. flucloxacillin, first-generation cephalosporin)</td></tr><tr><td>Typical duration 7&ndash;10 days</td></tr><tr><td>Device removal <strong>not</strong> required</td></tr><tr><td>Close outpatient follow-up to confirm resolution and detect progression</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Deep / implant-associated infection &mdash; management</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Device removal (partial or complete, depending on extent) is generally required for cure &mdash; retained hardware acts as a nidus for biofilm and persistent infection</td></tr><tr><td>IV antibiotics, with infectious diseases / microbiology input on agent selection and duration</td></tr><tr><td>Duration depends on severity and complications (e.g. epidural abscess, meningitis, vertebral osteomyelitis)</td></tr><tr><td>Reimplantation is generally considered only after infective symptoms have resolved for at least 90 days (per NACC), with normalised inflammatory markers and a clean, intact wound</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Red flags &mdash; escalate regardless of a superficial appearance</div><table style=\"margin:0\"><tr><th>Feature</th></tr><tr><td>New neurological deficit</td></tr><tr><td>Systemic sepsis or fever with haemodynamic compromise</td></tr><tr><td>Wound dehiscence or exposed hardware</td></tr><tr><td>Suspected epidural abscess, meningitis or vertebral osteomyelitis</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Prevention</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Perioperative prophylactic antibiotics (NACC / Surgical Care Improvement Project: limit to within 24 hours postoperatively for standard-risk patients)</td></tr><tr><td>Strict aseptic implantation technique</td></tr><tr><td>Careful patient selection and optimisation of infection risk factors</td></tr></table></div></div></div></div>","relevantReading":[{"label":"NACC recommendations for reducing the risk of infection from neurostimulation devices","source":"Neuromodulation","url":"https://www.neuromodulationjournal.org/article/S1094-7159(21)03507-8/abstract"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_acute_pain_chronic_opioid_001', 'MTF', '{"dateAdded":"2026-09-09","rotationIndex":102,"stem":"Regarding the management of acute pain in a patient established on chronic opioid therapy:","choices":["The chronic opioid should be continued, with only non-opioid analgesics added for the acute pain episode","Hospital admission is a good opportunity to taper the chronic opioid","Buprenorphine is a good choice for the acute pain, given its partial agonist properties","Patient-controlled analgesia (PCA) is best avoided","Naloxone should be avoided in an opioid-tolerant patient"],"correct":[false,false,false,false,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The goals in the acute / perioperative period are threefold: avoid precipitating withdrawal, achieve effective analgesia, and set up a safe, coordinated plan for ongoing care after discharge. All five statements are false.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; The baseline opioid should be continued to prevent withdrawal and maintain tolerance-adjusted analgesia, but it will not cover a new acute painful stimulus on its own. Opioid-tolerant patients usually need additional opioid (often at higher doses than an opioid-naive patient); multimodal non-opioid analgesia should supplement &mdash; not replace &mdash; appropriately titrated additional opioid.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; An acute painful admission is not the time to attempt opioid tapering. The priority is adequate analgesia; abruptly reducing the baseline opioid risks undertreated pain, withdrawal and distress. Tapering should be deferred to a stable outpatient setting once the acute problem has resolved.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Buprenorphine is a partial &mu;-opioid receptor agonist with high receptor affinity and a ceiling effect for respiratory depression, but it is a poor choice for a new acute pain: onset to full effect can take up to ~72 hours, and its partial-agonist behaviour is mainly relevant at the high doses used in opioid use disorder rather than at the low analgesic patch doses. A patient <em>already established</em> on maintenance buprenorphine is a separate situation &mdash; it is generally continued, with a full agonist added for the acute pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; PCA remains useful and is often preferred in this group, allowing patient-titrated dosing on top of baseline requirements. Background infusion rates and bolus doses usually need to be set higher than for an opioid-naive patient, with close monitoring of analgesic adequacy.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Naloxone is not contraindicated in opioid-tolerant patients: if there is life-threatening respiratory depression, airway and breathing take priority. However, standard bolus doses can precipitate severe acute withdrawal and abrupt loss of analgesia, so it should be given in small, carefully titrated increments, with re-titration of analgesia once the acute danger has passed.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Acute Pain Management in the Opioid-Tolerant Patient</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The goals in the perioperative / acute period are threefold: avoid precipitating withdrawal, achieve effective analgesia, and ensure a safe, coordinated plan for continuing care after discharge.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">General principles</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Continue the baseline (chronic) opioid to prevent withdrawal and maintain tolerance-adjusted baseline analgesia</td></tr><tr><td>Additional analgesia is required on top of baseline therapy &mdash; the baseline dose alone will not cover a new acute painful stimulus</td></tr><tr><td>Use multimodal analgesia (paracetamol, NSAIDs where appropriate, regional techniques, ketamine, gabapentinoids) as adjuncts to reduce total opioid requirement, not as a substitute for adequate opioid dosing</td></tr><tr><td>Involve the multidisciplinary team &mdash; the existing chronic pain or palliative care service alongside the acute pain team</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Dosing considerations</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Opioid-tolerant patients generally require higher opioid doses than opioid-naive patients for equivalent analgesia, reflecting pharmacological tolerance and, in some cases, opioid-induced hyperalgesia</td></tr><tr><td>PCA is appropriate and useful, but background infusion rates and bolus doses typically need upward adjustment compared with opioid-naive patients</td></tr><tr><td>Careful, individualised titration is needed, often with closer monitoring given the higher total doses involved</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Patients on opioid substitution therapy</div><table style=\"margin:0\"><tr><th>Drug</th><th>Approach</th></tr><tr><td>Methadone maintenance</td><td>Continue the maintenance dose; add short-acting opioids for the acute pain on top</td></tr><tr><td>Buprenorphine &mdash; low-dose transdermal (up to ~70 micrograms/hour)</td><td>Unlikely to meaningfully interfere with full agonists used for acute pain; generally continued</td></tr><tr><td>Buprenorphine &mdash; high-dose sublingual (opioid use disorder)</td><td>High receptor affinity and partial agonism can blunt added full agonists. Options: continue it and add higher-dose short-acting opioids, split the buprenorphine dose, or temporarily transition to a full agonist for the acute period &mdash; with specialist / addiction-medicine input</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Emergency reversal</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Naloxone is not contraindicated in opioid-tolerant patients with dangerous respiratory depression, but standard doses risk precipitating severe acute withdrawal and abrupt loss of analgesia</td></tr><tr><td>Use small, incremental, carefully titrated doses; re-titrate analgesia once the acute danger has passed</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Practical and system considerations</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>An acute admission is <strong>not</strong> the time to attempt opioid tapering &mdash; the priority is analgesia and avoiding withdrawal</td></tr><tr><td>Communicate clearly with the patient&rsquo;s regular prescriber (GP, pain service or substance-misuse service) about the admission and any medication changes</td></tr><tr><td>Discharge planning should include liaison with the regular prescriber and a clear plan for weaning any additional opioids started for the acute event</td></tr></table></div></div></div></div>","relevantReading":[{"label":"Perioperative management of opioid-tolerant patients","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30056-2/fulltext"},{"label":"Acute pain management in patients receiving opioids for chronic and cancer pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30548-6/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_splanchnic_nerves_coeliac_plexus_001', 'MTF', '{"dateAdded":"2026-09-09","rotationIndex":103,"stem":"Regarding the splanchnic nerves:","choices":["They are composed of postganglionic sympathetic fibres","The least splanchnic nerve passes through the diaphragm","The greater splanchnic nerve arises from T5–T9","Coeliac plexus block causes gastroparesis","Coeliac plexus block can be used for pain from pancreatic malignancy"],"correct":[false,true,true,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The splanchnic nerves (greater, lesser and least) carry <strong>preganglionic</strong> sympathetic fibres from the thoracic sympathetic chain to the prevertebral ganglia of the abdomen, where they synapse. The coeliac plexus, formed around the coeliac ganglia, is a common target for blockade of upper abdominal visceral pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; The splanchnic nerves are preganglionic. Their fibres leave the sympathetic chain ganglia <em>without</em> synapsing there and travel to the coeliac (and aorticorenal / superior mesenteric) ganglia, where the postganglionic fibres then arise to supply the abdominal viscera.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; All three splanchnic nerves (greater, lesser and least) pierce the crura of the diaphragm to reach the abdomen.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; The greater splanchnic nerve arises from the T5&ndash;T9 sympathetic ganglia (some texts quote T5&ndash;T10). The lesser splanchnic nerve arises from T10&ndash;T11 and the least splanchnic nerve from T12.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Coeliac plexus / splanchnic block does not cause gastroparesis. Interrupting sympathetic (inhibitory) tone leaves parasympathetic activity unopposed, which tends to <em>increase</em> gut motility &mdash; transient diarrhoea is the most common side effect. Orthostatic hypotension, from loss of splanchnic vasomotor tone, is also expected.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Coeliac plexus block or neurolysis is a well-established interventional technique for upper abdominal visceral pain from pancreatic malignancy and other upper GI malignancies (gastric, hepatobiliary). It is also used, with less durable benefit, in chronic pancreatitis. It interrupts sympathetic afferent nociceptive transmission from these structures.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Coeliac Plexus and Splanchnic Nerves</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The coeliac plexus lies anterior to the aorta at the level of the coeliac trunk (T12&ndash;L1) and is formed around the paired coeliac ganglia. Its preganglionic input is the three splanchnic nerves; its postganglionic fibres supply the foregut and midgut viscera.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Coeliac plexus &mdash; overview</div><div style=\"text-align:center\"><img src=\"images/coeliac-plexus.svg\" alt=\"Schematic of the splanchnic nerves and coeliac plexus: the greater (T5-T9), lesser (T10-T11) and least (T12) splanchnic nerves carry preganglionic sympathetic fibres that pierce the diaphragmatic crura and synapse in the coeliac ganglia, whose postganglionic fibres radiate to the foregut and midgut viscera\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy and origin</div><table style=\"margin:0\"><tr><th>Nerve</th><th>Origin</th><th>Course / termination</th></tr><tr><td>Greater splanchnic</td><td>T5&ndash;T9 sympathetic ganglia (preganglionic)</td><td>Pierces the crus of the diaphragm; synapses in the coeliac ganglion</td></tr><tr><td>Lesser splanchnic</td><td>T10&ndash;T11</td><td>Pierces the crus; synapses in the coeliac / superior mesenteric ganglion</td></tr><tr><td>Least (lowest) splanchnic</td><td>T12</td><td>Pierces the crus; synapses in the renal (aorticorenal) ganglion</td></tr></table><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">All three carry preganglionic sympathetic fibres &mdash; distinct from the postganglionic fibres that arise from the coeliac ganglion onward.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Structures supplied (via the coeliac plexus, postganglionic)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Stomach, liver, gallbladder, pancreas, spleen, kidneys, adrenal glands, small bowel and proximal large bowel to the splenic flexure &mdash; broadly the foregut and midgut structures.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications for blockade</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Visceral upper-abdominal pain from malignancy &mdash; most classically pancreatic cancer, also gastric and hepatobiliary tumours</td></tr><tr><td>Chronic pancreatitis pain (evidence and durability more limited than for malignant pain)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Physiological effects and complications of blockade</div><table style=\"margin:0\"><tr><th>Effect</th></tr><tr><td>Diarrhoea &mdash; the most common, expected effect (unopposed parasympathetic activity &rarr; increased gut motility); <strong>not</strong> gastroparesis</td></tr><tr><td>Orthostatic hypotension &mdash; loss of sympathetic vasomotor tone to the splanchnic vascular bed</td></tr><tr><td>Retroperitoneal haematoma / vascular injury &mdash; proximity to the aorta, IVC and other major vessels</td></tr><tr><td>Pneumothorax &mdash; with a transcrural or retrocrural approach</td></tr><tr><td>Paraplegia &mdash; rare; from injury to the artery of Adamkiewicz</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Approaches</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Anterocrural, retrocrural, transaortic, transdiscal, anterior (percutaneous or surgical) and endoscopic ultrasound-guided.</p></div></div></div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

